package explorer

import (
	"strings"

	"github.com/charmbracelet/lipgloss"

	"github.com/anthnel/devdesk/internal/jobs"
	"github.com/anthnel/devdesk/internal/ui/datatable"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// The clone list is the item level of a clone run (D3).
//
// It used to keep its own five states, its own rows, its own index and its own
// spinner frame — a fifth bookkeeping beside the four internal/jobs replaced,
// and the one the plan named as the prototype to generalise. Those five states
// are where jobs.ItemState came from, so the mapping is direct:
//
//	queued        → ItemQueued
//	cloning       → ItemRunning
//	cloned        → ItemDone
//	already there → ItemSkipped
//	failed        → ItemFailed
//
// What this screen is now is a **rendering** of the run: the rows are the
// snapshot's items, in the order the walk found them, and the frame is the
// router's (D5). Nothing here is authoritative, which is what lets `:jobs` show
// the same run without either copy drifting from the other.

// cloneRow is one target of the run, with the shared frame stamped on.
//
// The frame rides on the row because the columns are built once and close over
// nothing — the same reason jobsview has runRow. It is text rather than a
// rendered spinner because a table cell must carry no escape sequence
// (Rule 122).
type cloneRow struct {
	item  jobs.Item
	frame string
}

// cloneList is the ModeCloning screen: the run in flight and the table showing
// it. It is the progress view and the report both — decision 9 leaves modals
// for yes/no confirmations only.
type cloneList struct {
	table datatable.Model[cloneRow]

	// run is the last snapshot of this screen's run. It is a copy, replaced
	// whole on every broadcast — there is nothing to reconcile, which is what
	// removed the index and the upsert.
	run    jobs.Run
	target string

	// events is the pipeline's channel, and the only thing this struct still
	// owns. It is not state: it is what waitForCloneEvent blocks on.
	events <-chan cloneEvent

	// cancelling is set by `esc` and cleared by nothing: a run that is stopping
	// cannot be restarted, only awaited. A second `esc` must not force, because
	// forcing is the half-cloned directory decision 12 avoids.
	//
	// It is kept here rather than read back from the run for one frame's worth
	// of honesty: `esc` asks the router, and the answer arrives in the next
	// broadcast. Without it the key would look ignored until then.
	cancelling bool
}

const (
	colCloneStatusMin = 16
	colClonePathMin   = 30
	colCloneDetailMin = 20
)

// The column order, named so a test asserting on a cell does not hard-code the
// position it happens to sit at today.
const (
	colCloneRepository = iota
	colCloneDetail
	colCloneStatus
)

func newCloneList(target string, events <-chan cloneEvent) *cloneList {
	return &cloneList{
		target: target,
		events: events,
		table: datatable.New(datatable.Config[cloneRow]{
			Columns: cloneColumns(),
			// Discovery order, deliberately: it is the order things happened, and
			// a list that reorders itself while it fills is unreadable. `.` still
			// sorts on demand.
			SortColumn: -1,
		}),
	}
}

// cloneColumns describes the clone list.
//
// The repository comes first and the status last. The rows are one long list of
// paths under a common prefix, so the name is what the eye runs down to find a
// line; a status column on the left pushes every one of them right by sixteen
// cells and puts the changing text where the stable text should be.
func cloneColumns() []datatable.Column[cloneRow] {
	return []datatable.Column[cloneRow]{
		{
			Title: "Repository", Sizing: datatable.SizingContent, MinWidth: colClonePathMin, Flex: 2, TruncateHead: true,
			Cell:   func(r cloneRow) string { return r.item.Name() },
			Less:   func(a, b cloneRow) bool { return strings.ToLower(a.item.Name()) < strings.ToLower(b.item.Name()) },
			Search: func(r cloneRow) string { return r.item.Name() },
		},
		{
			Title: "Detail", Sizing: datatable.SizingContent, Optional: true, MinWidth: colCloneDetailMin, Flex: 1,
			Cell:   func(r cloneRow) string { return r.item.Detail },
			Search: func(r cloneRow) string { return r.item.Detail },
		},
		{
			Title: "Status", Sizing: datatable.SizingFixed, MinWidth: colCloneStatusMin,
			Cell:  cloneStatusLabel,
			Style: cloneStatusStyle,
			Less:  func(a, b cloneRow) bool { return a.item.State < b.item.State },
		},
	}
}

// cloneStatusLabel is the status cell: an icon and a word, plain text.
//
// The words are the clone's, not the registry's: "already there" is what a skip
// means here, where a sync's skip means something else entirely. The state is
// shared, the wording is the view's — the same split Reporter draws.
func cloneStatusLabel(r cloneRow) string {
	switch r.item.State {
	case jobs.ItemRunning:
		return r.frame + " cloning"
	case jobs.ItemDone:
		return theme.IconOK + " cloned"
	case jobs.ItemSkipped:
		return theme.IconSkipped + " already there"
	case jobs.ItemFailed:
		return theme.IconError + " failed"
	default:
		return theme.IconPending + " queued"
	}
}

// cloneStatusStyle colours the status cell.
//
// The five states are the whole vocabulary of this screen, and they are the one
// thing a run of forty rows is read for: which ones failed, which are still
// going, which were already on disk and were left alone.
func cloneStatusStyle(r cloneRow) lipgloss.Style {
	switch r.item.State {
	case jobs.ItemDone:
		return theme.StatusOKStyle
	case jobs.ItemFailed:
		return theme.StatusErrorStyle
	case jobs.ItemRunning:
		return lipgloss.NewStyle().Foreground(theme.ColorHighlight)
	default: // queued, and already there — neither is news
		return theme.DimStyle
	}
}

// setRun replaces the screen's copy of the run and rebuilds the table.
//
// The frame is stamped on the running rows here rather than held on each item,
// because it belongs to the list and not to any repository: one spinner, on
// every row that is going.
func (l *cloneList) setRun(run jobs.Run, frame string) {
	l.run = run
	items := make([]cloneRow, len(run.Items))
	for i, item := range run.Items {
		row := cloneRow{item: item}
		if item.State == jobs.ItemRunning {
			row.frame = frame
		}
		items[i] = row
	}
	l.table.SetItems(items)
}

// finished reports whether the run has settled: the walk sealed, and every
// target done with.
func (l *cloneList) finished() bool { return l.run.Finished() }

// running counts the clones still in flight, which is what `esc` has to wait
// for and what the view states while it does.
func (l *cloneList) running() int {
	n := 0
	for _, item := range l.run.Items {
		if item.State == jobs.ItemRunning {
			n++
		}
	}
	return n
}

// counts is the header line: what has been found and how it went.
func (l *cloneList) counts() (found, cloned, present, failed int) {
	c := l.run.Counts()
	return l.run.Total(), c[jobs.ItemDone], c[jobs.ItemSkipped], c[jobs.ItemFailed]
}

// failures returns the failed paths, for the log and the footer. Decision 13
// discards the list on `esc`, and workspaces records only the successes — a
// failure that wrote nothing leaves nothing behind, so it has to be said while
// the view is still alive.
func (l *cloneList) failures() []string {
	var out []string
	for _, item := range l.run.Items {
		if item.State == jobs.ItemFailed {
			out = append(out, item.Target)
		}
	}
	return out
}

// cloneRunFrom picks this screen's run out of the snapshot.
//
// The newest clone run, because there is exactly one at a time: ModeCloning
// owns the display while it goes, so a second could only start after this one
// has been closed. It is the invariant Registry.openRun rests on, read from the
// other side.
//
// A settled run still matches, which is what the report needs: the screen stays
// up after the walk has sealed, and `esc` is what finally drops it.
func cloneRunFrom(runs []jobs.Run) (jobs.Run, bool) {
	for i := len(runs) - 1; i >= 0; i-- {
		if runs[i].Kind == jobs.KindClone {
			return runs[i], true
		}
	}
	return jobs.Run{}, false
}

package explorer

import (
	"log"
	"slices"
	"strconv"
	"strings"

	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/command"
	"github.com/anthnel/devdesk/internal/forge"
	"github.com/anthnel/devdesk/internal/jobs"
	"github.com/anthnel/devdesk/internal/ui/datatable"
)

// The clone flow, end to end (§3.16):
//
//	c              → ModeSelecting, the tree with checkboxes
//	space          → tick the row; ←→ still drill, so deselecting means going in
//	enter          → borrow the workspaces view for a destination
//	                 (the selection survives the round trip — it names paths)
//	destination    → ModeCloning, the pipeline starts
//	esc            → cancel: discovery stops, running clones are awaited
//	esc (finished) → back to the tree, list discarded (decision 13)

// handleCloneStart enters the selection mode.
func (m Model) handleCloneStart() (tea.Model, tea.Cmd) {
	// Rule 130: C is greyed without a session, and a greyed key that is pressed
	// anyway says why rather than doing nothing. An empty level is not a
	// refusal worth a line — there is simply nothing to tick.
	if a := m.connected(); !a.Enabled() {
		return m, m.footer.Warn(a.Reason)
	}
	if len(m.nodes) == 0 {
		return m, nil
	}
	m.mode = ModeSelecting
	m.selection = newCloneSelection()
	m.selectionNodes = map[string]*TreeNode{}
	m.updateTableRows()
	return m, nil
}

// handleSelectionToggle ticks or unticks the row under the cursor (Space,
// Rule 135).
//
// The node is kept beside the path because the walk needs somewhere to start
// and a root ticked three levels down is not reachable from the current level
// once the user has come back up. The selection itself stays paths-only — it
// has to answer for descendants nobody has fetched.
func (m Model) handleSelectionToggle() (tea.Model, tea.Cmd) {
	node, ok := m.selectedNode()
	if !ok {
		return m, nil
	}
	// A row the forge has not confirmed cannot be cloned — there is nothing at
	// that path yet — and refusing it here is what lets the icon column give
	// the activity dot priority over the checkbox without the two ever competing.
	if act := m.actionable(); !act.Enabled() {
		return m, m.footer.Warn(act.Reason)
	}

	m.selection.toggle(node.FullPath)
	if m.selection.isRoot(node.FullPath) {
		m.selectionNodes[node.FullPath] = node
	} else {
		delete(m.selectionNodes, node.FullPath)
	}
	m.updateTableRows()
	return m, nil
}

// handleSelectionConfirm asks the app for a destination directory.
func (m Model) handleSelectionConfirm() (tea.Model, tea.Cmd) {
	if m.selection.isEmpty() {
		return m, m.footer.Warn("Nothing selected — press space to tick a group or a project")
	}
	return m, func() tea.Msg { return CloneSelectionRequestMsg{} }
}

// handleSelectionCancel leaves the selection mode, dropping the selection.
func (m Model) handleSelectionCancel() (tea.Model, tea.Cmd) {
	m.mode = ModeNormal
	m.selection = newCloneSelection()
	m.selectionNodes = nil
	m.updateTableRows()
	return m, nil
}

// handleCloneDestinationSelected starts the pipeline.
func (m Model) handleCloneDestinationSelected(msg CloneDestinationSelectedMsg) (tea.Model, tea.Cmd) {
	roots := m.rootNodes()
	if len(roots) == 0 {
		// The selection survived the round trip but named nothing reachable,
		// which is a bug rather than a user action — say so instead of opening
		// an empty list.
		log.Printf("ERROR [explorer] clone: the selection resolved to no nodes")
		cancelled, _ := m.handleSelectionCancel()
		m = cancelled.(Model)
		return m, m.footer.Error("Nothing to clone — check logs")
	}

	run := startCloneRun(cloneSpec{
		backend:         m.shared.Forge,
		roots:           roots,
		selection:       m.selection,
		target:          msg.Path,
		secrets:         m.shared.Secrets.Storage,
		cloneMethod:     forge.CloneMethod(m.config.Forge.CloneMethod),
		gitlabURL:       m.config.Forge.URL,
		jobs:            m.config.Forge.Pull.ParallelJobs,
		includeArchived: m.config.Forge.Pull.IncludeArchived,
	})

	m.mode = ModeCloning
	m.clone = newCloneList(msg.Path, run.events)
	m.clone.table.Resize(m.width, max(m.height-1, 1))
	// An **open** run: the walk that finds repositories is itself the slow
	// part, so there is no target list to register (D3). The cancel travels
	// with it because the pipeline was started here, in Update — which is also
	// what makes `esc` reach the registry rather than the channel behind its
	// back.
	return m, tea.Batch(
		jobs.StartCancellable(m.cloneJobRun(msg.Path), waitForCloneEvent(run.events), run.cancel),
		m.spinner.Tick,
	)
}

// cloneRun describes the batch to the registry. The destination names it: it is
// what a human recognises a clone by, and the roots are already in the rows.
func (m Model) cloneJobRun(target string) jobs.Run {
	return jobs.NewOpenRun(jobs.KindClone, command.ViewGitExplorer, "", target)
}

// rootNodes resolves the ticked paths to the nodes the walk starts from, in a
// stable order so two runs of the same selection read the same way.
func (m Model) rootNodes() []*TreeNode {
	paths := m.selection.rootPaths()
	nodes := make([]*TreeNode, 0, len(paths))
	for _, path := range paths {
		if node, ok := m.selectionNodes[path]; ok {
			nodes = append(nodes, node)
		}
	}
	return nodes
}

// handleCloneEvent logs what deserves logging and waits for the next event.
//
// It no longer folds anything in: the router applied the event to the registry
// before handing it here, and the rows arrive in the broadcast that follows
// (D1). What is left is the log and the re-issued read.
func (m Model) handleCloneEvent(msg CloneEventMsg) (tea.Model, tea.Cmd) {
	if m.clone == nil {
		return m, nil
	}
	if msg.event.kind == cloneEnded && msg.event.err != nil {
		log.Printf("ERROR [explorer] clone %s: %v", msg.event.path, msg.event.err)
	}
	if msg.event.kind == cloneWalkFailed {
		log.Printf("ERROR [explorer] discover %s: %v", msg.event.path, msg.event.err)
	}
	return m, waitForCloneEvent(m.clone.events)
}

// handleCloneRunFinished is the closed channel: the walk is over and every
// clone has returned. The router has sealed the run by the time this runs.
func (m Model) handleCloneRunFinished() (tea.Model, tea.Cmd) {
	if m.clone == nil {
		return m, nil
	}

	// Decision 13 keeps only what workspaces can show, and a failed clone wrote
	// nothing. Naming the failures now is the only record there will be.
	if failed := m.clone.failures(); len(failed) > 0 {
		return m, m.footer.Error(failureSummary(failed))
	}
	return m, nil
}

// handleJobsChanged takes the router's snapshot.
//
// Two screens read it. The clone list reads its own run. The tree reads, per
// row, the runs and failures of its own context (rowActivity filters by
// m.contextName and by kind), so a scan in `ws` or another context's failure
// paints nothing here.
//
// It is the only writer of m.jobs, m.failures and m.contextName, and nothing is
// reconciled: the snapshot replaces what was held rather than being merged.
func (m Model) handleJobsChanged(msg jobs.ChangedMsg) (tea.Model, tea.Cmd) {
	m.jobs = msg.Runs
	m.failures = slices.Clone(msg.Failures)
	m.contextName = msg.Context

	if m.clone != nil {
		if run, ok := cloneRunFrom(msg.Runs); ok {
			m.clone.setRun(run, m.jobFrame)
		}
		return m, nil
	}
	// The rows are rebuilt from the new snapshot.
	m.updateTableRows()
	return m, nil
}

// handleFrameMsg takes the animation's frame. The tree table reads the blink
// phase at render, so no tree row is rebuilt. The clone list keeps its own copy
// of the run and its frame (A-10b); only the frame is rebuilt into it.
func (m Model) handleFrameMsg(msg jobs.FrameMsg) (tea.Model, tea.Cmd) {
	m.jobFrame = msg.Frame
	m.footer.SetSpinnerFrame(msg.RenderedFrame)
	m.table.SetBlinkPhase(msg.Blink)

	if m.clone != nil {
		m.clone.setRun(m.clone.run, msg.Frame)
	}
	return m, nil
}

// ActivityTables returns the read-only face of the tree table, keyed by the
// name the activity-column guard (internal/app) knows it by.
func (m Model) ActivityTables() map[string]datatable.ActivityTable {
	return map[string]datatable.ActivityTable{"explorer/tree": &m.table}
}

// failureSummary names one failure and counts the rest — the footer is one line.
func failureSummary(failed []string) string {
	if len(failed) == 1 {
		return "Failed to clone " + failed[0] + " — check logs"
	}
	return "Failed to clone " + failed[0] + " and " +
		plural(len(failed)-1, "other") + " — check logs"
}

func plural(n int, word string) string {
	if n == 1 {
		return "1 " + word
	}
	return strconv.Itoa(n) + " " + word + "s"
}

// handleCloneEsc cancels a running pipeline, or closes a finished one.
//
// The two are one key because they are one intent — "I am done with this" — and
// separating them would need the user to know which state the list is in. A
// second press while cancelling does nothing: forcing would mean killing a
// `git clone` mid-write, which is the half-repository decision 12 rules out.
func (m Model) handleCloneEsc() (tea.Model, tea.Cmd) {
	if m.clone == nil {
		m.mode = ModeNormal
		return m, nil
	}
	if m.clone.finished() {
		return m.handleCloneClose()
	}
	if m.clone.cancelling {
		return m, nil
	}

	// The registry stops the run: it holds the cancel, and it is what marks the
	// run cancelled so `:jobs` says "cancelled" rather than "done". Calling the
	// pipeline's cancel from here would stop the walk behind the registry's
	// back, and leave the record claiming the run finished on its own.
	m.clone.cancelling = true
	return m, jobs.CancelOpen(jobs.KindClone)
}

// handleCloneClose discards the list and returns to the tree.
func (m Model) handleCloneClose() (tea.Model, tea.Cmd) {
	m.clone = nil
	m.selection = newCloneSelection()
	m.selectionNodes = nil
	m.mode = ModeNormal
	m.updateTableRows()
	return m, nil
}

// cloneStatusLine is what the view puts under the list: what the run is doing,
// then what it did.
func (m Model) cloneStatusLine() string {
	if m.clone == nil {
		return ""
	}
	found, cloned, present, failed := m.clone.counts()

	var b strings.Builder
	switch {
	case m.clone.finished():
		b.WriteString("Done — ")
	case m.clone.cancelling:
		b.WriteString("Cancelling — " + plural(m.clone.running(), "clone") + " finishing · ")
	default:
		b.WriteString(strconv.Itoa(found) + " found · ")
	}
	b.WriteString(strconv.Itoa(cloned) + " cloned · " + strconv.Itoa(present) + " already there")
	if failed > 0 {
		b.WriteString(" · " + strconv.Itoa(failed) + " failed")
	}
	return b.String()
}

package explorer

import "github.com/anthnel/devdesk/internal/jobs"

// What each clone event tells the registry (jobs.Reporter).
//
// The mapping lives here and not in the router, for the reason Reporter exists:
// "a repository that was already on disk is a skip, and it is not news" is this
// package's vocabulary, and a router that knew it would grow a branch per view.
//
// cloneFound and cloneWalkFailed both set Discover, because both name a target
// the run has never heard of — the walk is what finds them (D3). The others
// address a row that exists.

func (m CloneEventMsg) Transition() jobs.Transition {
	t := jobs.Transition{Kind: jobs.KindClone, Target: m.event.path}
	switch m.event.kind {
	case cloneFound:
		t.State, t.Discover = jobs.ItemQueued, true
	case cloneBegan:
		t.State = jobs.ItemRunning
	case cloneEnded:
		switch {
		case m.event.err != nil:
			t.State, t.Detail = jobs.ItemFailed, m.event.err.Error()
		case m.event.skipped:
			// Not a failure and not work: the directory was already there, and
			// decision 2 says the explorer leaves what exists alone.
			t.State = jobs.ItemSkipped
		default:
			t.State = jobs.ItemDone
		}
	case cloneWalkFailed:
		// A group that could not be listed gets a row of its own rather than
		// being folded into a repository's error: the repositories under it
		// were never discovered, so no other row can stand for them. It is
		// discovered *as* a failure — there was never a queued state for it.
		t.State, t.Detail, t.Discover = jobs.ItemFailed, "discovery: "+m.event.err.Error(), true
	}
	return t
}

// Seal says the walk is over (jobs.Sealer). Until it is called the run is
// unsettled whatever its rows say: a walk that has found three repositories and
// cloned all three is not done.
func (CloneRunFinishedMsg) Seal() jobs.Kind { return jobs.KindClone }

// Compile-time proof that the two messages carry what the registry needs. One
// added without it would be routed, would update the view, and would leave its
// row spinning for the life of the screen.
var (
	_ jobs.Reporter = CloneEventMsg{}
	_ jobs.Sealer   = CloneRunFinishedMsg{}
)

