62	// loadingTree reports whether the group tree is still being fetched.
63	func (m Model) loadingTree() bool { return m.loading || !m.firstLoadDone }
64	
65	// renderTable renders the table content
66	func (m Model) renderTable() string {
67		return m.table.View()
68	}
69	
70	// GetFooterHeight returns the footer height for this view (Rule 124).
71	//
72	// The clone list has no breadcrumb — it is a flat list, and the tree's path
73	// says nothing about it — so it takes the two-line footer plus its own filter
74	// bar.
75	func (m Model) GetFooterHeight() int {
76		if m.mode == ModeFuzzyFinding && m.finder != nil {
77			return fuzzy.FooterHeight
78		}
79		if m.mode == ModeCloning && m.clone != nil {
80			return 2 + m.clone.table.FilterBar().ExtraHeight()
81		}
82		if m.showsTree() {
83			// filter bar (when visible) + breadcrumb tab bar + empty line + info line
84			return 3 + m.table.FilterBar().ExtraHeight()
85		}
86		return 2 // empty line + info line
87	}
88	
89	// RenderFooter returns the footer content rendered below the viewport (Rule 124).
90	func (m Model) RenderFooter(width int) string {
91		if m.mode == ModeFuzzyFinding && m.finder != nil {
92			return m.finder.RenderFooter(width, &m.footer)
93		}
94		infoLine := m.renderInfoLine(width)
95	
96		if m.mode == ModeCloning && m.clone != nil {
97			var parts []string
98			if bar := m.clone.table.FilterBar(); bar.IsVisible() {
99				parts = append(parts, bar.View())
100			}
101			return strings.Join(append(parts, theme.EmptyLineBg(width), infoLine), "\n")
102		}
103	
104		if m.showsTree() {
105			var parts []string
106			if bar := m.table.FilterBar(); bar.IsVisible() {
107				parts = append(parts, bar.View())
108			}
109			parts = append(parts, m.renderTabBar(), theme.EmptyLineBg(width), infoLine)
110			return strings.Join(parts, "\n")
111		}
112		return theme.EmptyLineBg(width) + "\n" + infoLine
113	}
114	
115	// renderInfoLine is the footer's one line of text (Rule 128): a message when
116	// there is one, otherwise whatever the current mode has to say.
117	func (m Model) renderInfoLine(width int) string {
118		return m.footer.View(width, m.status())
119	}
120	
121	// status is what the view derives on every frame. None of the five has a timer:
122	// a clone run outlives the three seconds a message gets, and the load, the
123	// selection, the missing session and the failed load last exactly as long as
124	// they last.
125	func (m Model) status() components.Status {
126		switch {
127		// Signed out and a failed load are states, not events: they are true for as
128		// long as they are true, so they carry the error level and no timer (Rule
129		// 128). A three-second message would leave an empty table explaining
130		// nothing for the rest of the session.
131		case !m.shared.IsAuthenticated:
132			return components.Status{Text: notAuthenticatedLine(m.vocab()), Level: components.LevelError}
133		case m.mode == ModeCloning && m.clone != nil:
134			return components.Status{Text: m.cloneStatusLine()}
135		case m.mode == ModeSelecting:
136			return components.Status{Text: m.selectionStatusLine()}
137		case m.error != "":
138			return components.Status{Text: m.error, Level: components.LevelError}
139		}
140		st := components.Status{}
