// GetFooterHeight returns the footer height for this view (Rule 124).
//
// The clone list has no breadcrumb — it is a flat list, and the tree's path
// says nothing about it — so it takes the two-line footer plus its own filter
// bar.
func (m Model) GetFooterHeight() int {
	if m.mode == ModeFuzzyFinding && m.finder != nil {
		return fuzzy.FooterHeight
	}
	if m.mode == ModeCloning && m.clone != nil {
		return 2 + m.clone.table.FilterBar().ExtraHeight()
	}
	if m.showsTree() {
		// filter bar (when visible) + breadcrumb tab bar + empty line + info line
		return 3 + m.table.FilterBar().ExtraHeight()
	}
	return 2 // empty line + info line
}

// RenderFooter returns the footer content rendered below the viewport (Rule 124).
func (m Model) RenderFooter(width int) string {
	if m.mode == ModeFuzzyFinding && m.finder != nil {
		return m.finder.RenderFooter(width, &m.footer)
	}
	infoLine := m.renderInfoLine(width)

	if m.mode == ModeCloning && m.clone != nil {
		var parts []string
		if bar := m.clone.table.FilterBar(); bar.IsVisible() {
			parts = append(parts, bar.View())
		}
		return strings.Join(append(parts, theme.EmptyLineBg(width), infoLine), "\n")
	}

	if m.showsTree() {
		var parts []string
		if bar := m.table.FilterBar(); bar.IsVisible() {
			parts = append(parts, bar.View())
		}
		parts = append(parts, m.renderTabBar(), theme.EmptyLineBg(width), infoLine)
		return strings.Join(parts, "\n")
	}
	return theme.EmptyLineBg(width) + "\n" + infoLine
}

// renderInfoLine is the footer's one line of text (Rule 128): a message when
// there is one, otherwise whatever the current mode has to say.
func (m Model) renderInfoLine(width int) string {
	return m.footer.View(width, m.status())
}

// status is what the view derives on every frame. None of the five has a timer:
// a clone run outlives the three seconds a message gets, and the load, the
// selection, the missing session and the failed load last exactly as long as
// they last.
func (m Model) status() components.Status {
	switch {
	// Signed out and a failed load are states, not events: they are true for as
	// long as they are true, so they carry the error level and no timer (Rule
	// 128). A three-second message would leave an empty table explaining
	// nothing for the rest of the session.
	case !m.shared.IsAuthenticated:
		return components.Status{Text: notAuthenticatedLine(m.vocab()), Level: components.LevelError}
	case m.mode == ModeCloning && m.clone != nil:
		return components.Status{Text: m.cloneStatusLine()}
	case m.mode == ModeSelecting:
		return components.Status{Text: m.selectionStatusLine()}
	case m.error != "":
		return components.Status{Text: m.error, Level: components.LevelError}
	}
	st := components.Status{}
	switch {
	case m.loadingTree():
		st = components.Status{Text: "Loading " + m.vocab().Name + " " + strings.ToLower(m.vocab().Namespaces) + "...", Spinner: true}
	// A level on screen from the index while the forge is asked again: the
	// rows are there, so this is the lowest-priority line, and it says what
	// is still coming rather than that anything is missing.
	case m.refreshing > 0:
		st = components.Status{Text: "Updating from " + m.vocab().Name + "...", Spinner: true}
	}
	// The selected row says what it is doing, or what last went wrong on it.
	// Selection mode returned above, so its checkbox column keeps the line.
	if node, ok := m.selectedNode(); ok {
		st.Detail = m.rowActivity(node).Detail
	}
	return st
}

